function CatHouseExploreTaskHarvestPanel:Init()
    SetButtonAction(self.BtnStart.gameObject, Bind(self, self.ActionOnBtnStart))
    SetButtonAction(self.BtnAutoFormation.gameObject, Bind(self, self.ActionOnBtnAutoFormation))
end

function CatHouseExploreTaskHarvestPanel:SetPanelInfo(taskData, exploreId)
    self.taskData = taskData
    self.exploreId = exploreId
    print("->CatHouseExploreTaskHarvestPanel:SetPanelInfo:", 
            table.dump(checkTable(CatHouseExploreMgr:GetExploreData(self.exploreId))), 
            table.dump(checkTable(self.taskData)))
    self:SetTextPlayerHPCost(self.taskData.playerStrengthNum)
    self:SetTextCountDown(self.taskData.taskTime)
end

function CatHouseExploreTaskHarvestPanel:ActionOnBtnStart()
    --if isNull(CatHouseExploreMgr.listCatsTeam) or #CatHouseExploreMgr.listCatsTeam <= 0 then return end
    local attributeValue = checkNumber(CatHouseExploreMgr:GetCatsListTaskAttributeValue(checkNumber(self.taskData.attributeId)))
    local attributeValueLimit = checkNumber(self.listAttributeCondition[1].numLevel)
    local hpValue = GoodsUtils.GetThingNo(checkNumber(self.taskData.playerStrengthId)) --体力
    print("->CatHouseExploreTaskHarvestPanel:ActionOnBtnStart", checkNumber(self.exploreId), attributeValue, attributeValueLimit, hpValue, checkNumber(self.taskData.playerStrengthNum))
    if hpValue < checkNumber(self.taskData.playerStrengthNum) then
        UIModule.OpenDialog({id = Constants.UITypeIds.UIHPDialog, parameters = { overrideSorting = 1050 } })
        return
    end
    if attributeValue < attributeValueLimit then
        GameUtils.Toast(localize("未满足最低属性要求"))
        return
    end
    if not isNull(CatHouseExploreMgr.listCatsTeam) and checkNumber(#CatHouseExploreMgr.listCatsTeam) > 0 then
        local exploreId = checkInt(self.exploreId)
        local teamCats = checkString(CatHouseExploreMgr:GetStringCatsTeamExploreStart())
        CatHouseExploreMgr:CatHouseExploreStartReq(exploreId, teamCats, function(rewards)
            if rewards ~= nil and next(rewards) ~= nil then
                UIRaycastBlocker:AddCondition("CatHouseExplore.PopRewards")
                GoodsUtils.DrawRewards(rewards)
                cs_coroutine.start(function ()
                    cs_coroutine.yield_return(UIModule.BackDialog())
                    UIRaycastBlocker:RemoveCondition("CatHouseExplore.PopRewards")
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
                end)
            else
                UIModule.BackDialog()
            end
            
        end)
    end
end

function CatHouseExploreTaskHarvestPanel:ActionOnBtnAutoFormation()
    print("->CatHouseExploreTaskHarvestPanel:ActionOnBtnAutoFormation")
    xTry(function()
        local cats = CatHouseExploreMgr:FunctionOnBtnAutoFormation(self.exploreId)
        if IsNull(cats) or  checkNumber(#cats) <= 0 then
            GameUtils.Toast(localize("当前没有符合要求的猫咪"))
        end
        Events.Broadcast(Constants.EventNames.CatHouseExploreAutoFormation)
    end)
end

