        self.TextPlayerHPCost.text = checkString(string.format("x%d", value))
    end
end

function CatHouseExploreTaskHarvestPanel:SetTextCountDown(value)
    if not isNull(self.TextCountDown) then
        self.TextCountDown.text = checkString(CfUtils.GetTimeHMS(value))
    end
end

function CatHouseExploreTaskHarvestPanel:RefreshTaskCondition(attributeValue)
    xTry(function()
        self.attributeValue = checkInt(attributeValue)
        self.listAttributeCondition = CatHouseExploreMgr:GetTaskAttributeCondition(self.taskData.taskId)
        self.listExtraCondition = CatHouseExploreMgr:GetTaskExtraCondition(self.taskData.taskId)
        self.extraConditionFinishedList = checkTable(CatHouseExploreMgr:GetFinishedExtraCondition(self.exploreId, self.taskData.taskId))
        print("->ConditionExtra:", table.dump(self.extraConditionFinishedList))
        self:RefreshListLevelAttribute()
        self:RefreshAwardNode(self.RewardAttribute, self.listAttributeCondition, "numLevel", self.attributeValue)
        self:RefreshListLevelExtra()
        self:RefreshExtraAward(self.RewardExtra, self.listExtraCondition, self.extraConditionFinishedList)
    end)
end

function CatHouseExploreTaskHarvestPanel:RefreshExtraAward(node, conditions, listFinish)
    conditions = checkTable(conditions)
    listFinish = checkTable(listFinish)
    if #conditions <= 0 then return end
    local isNullAward
    isNullAward = #listFinish <= 0
    local _getRewardId = function()
        return checkNumber(conditions[#listFinish].awardId)
    end
    local _getRewardNum = function()
        local num = 0
        for i = 1, #listFinish do
            num = num + checkNumber(conditions[checkNumber(listFinish[i])].awardNum)
        end
        return num
    end
    local rewardId = isNullAward and checkNumber(conditions[1].awardId) or _getRewardId()
    local goodNodeData = {
        goodsId = rewardId, -- goodId
        text = checkString(string.format("x%d", isNullAward and 0 or checkNumber(_getRewardNum()))), -- 数量显示,
        isShowNo = true
    }
    node:Init()
    node.Env:Reload(goodNodeData)
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodNodeData.goodsId)
    if isTable(vo) then
        node.Env:SetClickButtonAction(function()
            GameUtils.ShowCommonTipsBoard(node.gameObject, vo.name, vo.desc, vo.quality, vo.id)
        end)
    end
    print("ExtraGoods", table.dump(goodNodeData), node)
end

function CatHouseExploreTaskHarvestPanel:RefreshAwardNode(node, list, key, value)
    ---获取档位奖励
    local _functionGetLevelAward = function(pList, pKey, pValue)
        for i = #pList, 1, -1 do
            if pValue >= pList[i][checkString(pKey)] then
                return pList[i], i
            end
        end
        return nil, nil
    end
    ---获取档位可获得的奖励数量
    local _functionGetLevelAwardNum = function(pList, pKey, index)
        local result = 0  
        for i = 1, #pList do
            if i <= index then
                result = result + checkNumber(pList[i][checkString(pKey)])
            end
        end
        return result
    end
    local isNullAward
    local awardData, index = _functionGetLevelAward(list, key, value)
    isNullAward = IsNull(awardData)
    awardData = IsNull(awardData) and list[1] or awardData
    if isNull(awardData) then return end
    local awardNum = checkNumber(_functionGetLevelAwardNum(list, "awardNum", checkNumber(index)))
    local goodNodeData = {
        goodsId = awardData.awardId, -- goodId
        text = checkString(string.format("x%d", isNullAward and checkNumber(0)  or checkNumber(awardNum))), -- 数量显示,
        isShowNo = true 
    }
    node:Init()
    node.Env:Reload(goodNodeData)
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodNodeData.goodsId)
    if isTable(vo) then
        node.Env:SetClickButtonAction(function()
            GameUtils.ShowCommonTipsBoard(node.gameObject, vo.name, vo.desc, vo.quality, vo.id)
        end)
    end
    print("GoodsData", table.dump(goodNodeData), node)
end

function CatHouseExploreTaskHarvestPanel:RefreshListLevelAttribute()
    if isNull(self.taskData) then return end
    if self.ListLevelAttribute.IsListViewInit then
        GameUtils.ReloadData(self.ListLevelAttribute, table.count(self.listAttributeCondition))
    else
        self.ListLevelAttribute:InitGridView(table.count(self.listAttributeCondition), Bind(self, self.OnGetItemByIndexListAttribute))
    end
end

function CatHouseExploreTaskHarvestPanel:OnGetItemByIndexListAttribute(gridView, index, row, column)
    if index < 0 then return end
    local indexInTaskData = index + 1
    local attributeData = self.listAttributeCondition[indexInTaskData]
    local prefabPath = PREFAB_ITEM_CELL
    local cell = gridView:NewListViewItem(prefabPath)
    if not IsNull(cell) then
        ---条件描述
        local transDesc = cell.transform:Find("Layout/TextDescribe")
        if not isNull(transDesc) then
            local txtDesc = KTool.GetOrAddComponent(transDesc.gameObject, typeof(Text))
            local stDesc = KTool.GetOrAddComponent(transDesc.gameObject, typeof(UISwitchText))
            txtDesc.text = checkString(attributeData.desc)..checkString(attributeData.numLevel)
            stDesc.Status = self.attributeValue >= checkNumber(attributeData.numLevel) and 1 or 2
        end
        ---条件加成数值
        local transNumAdd = cell.transform:Find("Layout/TextReward")
        if not IsNull(transNumAdd) then
            local txtDesc = KTool.GetOrAddComponent(transNumAdd.gameObject, typeof(Text))
            local stDesc = KTool.GetOrAddComponent(transNumAdd.gameObject, typeof(UISwitchText))
            txtDesc.text = localize("奖励+_num_", {_num_ = checkString(attributeData.awardNum)})
            stDesc.Status = self.attributeValue >= checkNumber(attributeData.numLevel) and 1 or 2
        end
        ---条件达成标识
        local transIMGArea = cell.transform:Find("Layout/ImgArea")
        if not isNull(transIMGArea) then
            KTool.SetActive(transIMGArea.gameObject,self.attributeValue >= checkNumber(attributeData.numLevel))
        end
        KTool.SetActive(cell.gameObject, true)
    end
    return cell
end

function CatHouseExploreTaskHarvestPanel:RefreshListLevelExtra()
    KTool.SetActive(self.Content.gameObject, #self.listExtraCondition > 0 )
    KTool.SetActive(self.Empty.gameObject, #self.listExtraCondition <= 0)
    if #self.listExtraCondition <= 0 then return end
    if self.ListLevelExtra.IsListViewInit then
        GameUtils.ReloadData(self.ListLevelExtra, table.count(self.listExtraCondition))
    else
        self.ListLevelExtra:InitGridView(table.count(self.listExtraCondition), Bind(self, self.OnGetItemByIndexListExtra))
    end
end

function CatHouseExploreTaskHarvestPanel:OnGetItemByIndexListExtra(gridView, index, row, column)
    if index < 0 then return end
    local indexInTaskData = index + 1
    local extraData = self.listExtraCondition[indexInTaskData]
    local isFinished = checkBool(table.isContain(self.extraConditionFinishedList, indexInTaskData))
    local prefabPath = PREFAB_ITEM_CELL
    local cell = gridView:NewListViewItem(prefabPath)
    if not IsNull(cell) then
        KTool.SetActive(cell.gameObject, true)
        ---条件描述
        local transDesc = cell.transform:Find("Layout/TextDescribe")
        if not isNull(transDesc) then
            local txtDesc = KTool.GetOrAddComponent(transDesc.gameObject, typeof(Text))
            local stDesc = KTool.GetOrAddComponent(transDesc.gameObject, typeof(UISwitchText))
            local descCondition = checkString(CatHouseExploreMgr:GetCatHouseSpecialConditionData(extraData.numLevel).condition)
            local valueRequire = checkNumber(CatHouseExploreMgr:GetExploreRequireData(self.exploreId)[checkString(indexInTaskData)])
            descCondition = CatHouseExploreMgr:GetExtraConditionDesc(descCondition, extraData.numLevel, valueRequire)
            txtDesc.text = descCondition
            stDesc.Status = isFinished and 1 or 2
        end
        ---条件加成数值
        local transNumAdd = cell.transform:Find("Layout/TextReward")
        if not IsNull(transNumAdd) then
            local txtDesc = KTool.GetOrAddComponent(transNumAdd.gameObject, typeof(Text))
            local stDesc = KTool.GetOrAddComponent(transNumAdd.gameObject, typeof(UISwitchText))
            txtDesc.text = string.format("+%s", checkString(extraData.awardNum))
            stDesc.Status = isFinished and 1 or 2
        end
        ---条件达成标识
        local transIMGArea = cell.transform:Find("Layout/ImgArea")
        if not isNull(transIMGArea) then
            KTool.SetActive(transIMGArea.gameObject,isFinished)
        end
    end
    return cell
end

return CatHouseExploreTaskHarvestPanel